<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';admin_require_login();$q=trim((string)($_GET['q']??''));$sql="SELECT u.id,u.full_name,u.email,u.phone,u.status,u.created_at,COUNT(o.id) order_count,COALESCE(SUM(CASE WHEN o.status <> 'cancelled' THEN o.total_amount ELSE 0 END),0) order_value FROM users u LEFT JOIN orders o ON o.user_id=u.id WHERE u.role='customer'";$params=[];if($q!==''){$sql.=' AND (u.full_name LIKE ? OR u.email LIKE ? OR u.phone LIKE ?)';$l='%'.$q.'%';$params=[$l,$l,$l];}$sql.=' GROUP BY u.id ORDER BY u.created_at DESC LIMIT 250';$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();admin_page_start('Customers');?><div class="panel"><form method="get" class="d-flex gap-2 mb-3"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search name, email or phone" style="max-width:400px"><button class="btn btn-outline-secondary">Search</button></form><div class="table-responsive"><table class="table"><thead><tr><th>Customer</th><th>Phone</th><th>Account</th><th>Orders</th><th>Order value</th><th>Joined</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="text-center text-secondary py-4">No registered customers found.</td></tr><?php else:foreach($rows as $r):?><tr><td><strong><?=e($r['full_name'])?></strong><div class="small text-secondary"><?=e($r['email'])?></div></td><td><?=e($r['phone']??'—')?></td><td><?=e(ucfirst($r['status']))?></td><td><?=(int)$r['order_count']?></td><td><?=e(money($r['order_value']))?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;endif;?></tbody></table></div><p class="small text-secondary mb-0">This page lists registered customer accounts only. Guest orders may not be linked to a user.</p></div><?php admin_page_end();?>
